function payrollFilterBarHTML(base,filtered){const depts=[...new Set(base.map(payrollDeptOf))].sort((a,b)=>{let i=PAYROLL_DEPT_ORDER.indexOf(a),j=PAYROLL_DEPT_ORDER.indexOf(b);if(i<0)i=98;if(j<0)j=98;return i-j||a.localeCompare(b,'ar')});const closedCount=filtered.filter(s=>closedPayroll(s.id)).length;const draftPeople=filtered.filter(s=>!closedPayroll(s.id)&&!!db.payrollDrafts[payrollKey(s.id)]);const readyDrafts=draftPeople.filter(s=>{try{const d=payrollDraft(s.id);return moneyCents(d.hourlyRate)>0&&!!payrollTypes[d.type]}catch{return false}}).length;const incompleteDrafts=draftPeople.length-readyDrafts;const g=$('#branch');const branchOpts=g?[...g.options].map(o=>o.text):[];const curBranch=g?g.value:'';return `<div class="toolbar payroll-filter no-print" id="payrollFilterBar"><label>القسم <select id="payrollFilterDept"><option value="">كل الأقسام</option>${depts.map(d=>`<option value="${esc(d)}" ${payrollFilterDept===d?'selected':''}>${esc(d)}</option>`).join('')}</select></label><label>الفرع <select id="payrollFilterBranch">${branchOpts.map(b=>`<option value="${esc(b)}" ${curBranch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><label>الحالة <select id="payrollFilterStatus"><option value="">الكل</option><option value="closed" ${payrollFilterStatus==='closed'?'selected':''}>المقفولين بس</option><option value="open" ${payrollFilterStatus==='open'?'selected':''}>اللي لسه متقفلوش</option></select></label><span class="payroll-filter-count">${payrollFilterDept?esc(payrollFilterDept)+' — ':''}مقفول ${closedCount} من ${filtered.length} • مسودات ${draftPeople.length} (${readyDrafts} ببيانات أجر${incompleteDrafts?' • '+incompleteDrafts+' غير مكتملة':''})</span></div>`}
function payrollFind(id){return allEmployees().find(s=>s.id===id)||payrollExternalAll().find(x=>x.id===id)}
function normPayName(n){return String(n||'').trim().replace(/\s+/g,' ').replace(/[أإآ]/g,'ا').replace(/ى/g,'ي').replace(/ة/g,'ه').toLowerCase()}
function payrollExtFormHTML(){return `<form class="payroll-ext no-print" id="payrollExtForm"><input name="extName" placeholder="اسم موظف مش موجود في القائمة (من غير حساب)" maxlength="60" autocomplete="off"><button class="primary">＋ إضافة للتقفيل</button><small>للناس اللي لسه معندهاش حساب على النظام — بيتقفل بالساعات اليدوية بس، ومبيلمسش أي حساب أو ملف حقيقي، واسمه بيظهر في الكشف وتقرير الفرع بعلامة «اسم يدوي».</small></form>`}
function addPayrollExternal(name){const nm=String(name||'').trim().replace(/\s+/g,' ');if(nm.length<2)throw Error('اكتب اسم الموظف كامل');const key=normPayName(nm);if(allEmployees().some(s=>normPayName(s.name)===key))throw Error('«'+nm+'» موجود في النظام بالفعل — اختاره من القائمة');db.payrollExternal??=[];if(db.payrollExternal.some(x=>normPayName(x.name)===key))throw Error('«'+nm+'» متضاف قبل كده — اختاره من القائمة');const sel=$('#branch').value;const branch=sel==='كل الفروع'?((db.branches[0]||{}).name||''):sel;const rec={id:'ext-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,7),name:nm,branch,createdAt:new Date().toISOString()};db.payrollExternal.push(rec);audit('إضافة اسم يدوي للتقفيل: '+nm);payrollEmployee=rec.id;render();toast('اتضاف «'+nm+'» — حدد نوعه وسعر ساعته واكتب ساعاته اليدوية')}
function removePayrollExternal(id){const rec=(db.payrollExternal||[]).find(x=>x.id===id);if(!rec)return;if((db.payrollRuns||[]).some(r=>r.employeeId===id))return toast('فيه تقفيلة محفوظة بالاسم ده — الاسم بيفضل محفوظ في السجل');if(!confirm('حذف «'+rec.name+'» من قائمة التقفيل؟ المسودات المحفوظة باسمه هتتمسح كمان.'))return;db.payrollExternal=db.payrollExternal.filter(x=>x.id!==id);for(const k of Object.keys(db.payrollDrafts||{}))if(k.startsWith(id+':'))delete db.payrollDrafts[k];delete db.hourlyProfiles[id];audit('حذف اسم يدوي من التقفيل: '+rec.name);if(payrollEmployee===id)payrollEmployee=null;render();toast('اتحذف «'+rec.name+'»')}
