function closedPayroll(id,period=payrollPeriod){const runs=(db.payrollRuns||[]).filter(r=>r.employeeId===id&&r.status==='closed'&&r.period.from<=period.to&&r.period.to>=period.from);return runs.find(r=>r.period.from===period.from&&r.period.to===period.to)||runs.sort((a,b)=>String(b.closedAt).localeCompare(String(a.closedAt)))[0]||null}
function payrollAvailableEmployees(){const branch=$('#branch').value;return allEmployees().filter(s=>(branch==='كل الفروع'||s.branch===branch)&&(!db.archived.some(a=>a.id===s.id)||db.punches.some(p=>p.employeeId===s.id)||(db.attendanceOpening||[]).some(o=>Number(o.employeeId)===Number(s.id))))}
