function savedSnapshot(id,period=payrollPeriod){const employee=payrollFind(id);if(!employee)throw Error('الموظف غير موجود');const draft=structuredClone(payrollDraft(id,period)),attendance=attendanceHours(id,period),calculation=payrollCompute(draft,attendance,classPayFor(id,period));return {employeeId:id,employeeName:employee.name,branch:employee.branch,...(employee.external?{external:true}:{}),period:structuredClone(period),draft,attendance,calculation}}
function closePayroll(id,period=payrollPeriod){if(closedPayroll(id,period))throw Error('الفترة مقفولة بالفعل');if(period.to>cairoDay())throw Error('لا يمكن تقفيل فترة مستقبلية');const clash=db.payrollRuns.find(r=>r.employeeId===id&&r.status==='closed'&&r.period.from<=period.to&&r.period.to>=period.from);if(clash)throw Error('فيه تقفيل قائم ومتداخل مع الفترة دي؛ راجعه قبل إنشاء تقفيل جديد');const snapshot=savedSnapshot(id,period);if(snapshot.attendance.overlap)throw Error('في سجلات حضور متداخلة؛ صححها قبل التقفيل');if(!snapshot.attendance.closed.length&&!snapshot.attendance.opening?.length&&!(snapshot.calculation.manualHours>0))throw Error('لا توجد ساعات حضور مغلقة أو رصيد افتتاحي أو ساعات يدوية في الفترة');if(snapshot.calculation.rate<=0)throw Error('سعر الساعة لازم يكون أكبر من صفر للتقفيل');const run={id:crypto.randomUUID(),...snapshot,excludedOpenShiftCount:snapshot.attendance.open.length,closedAt:new Date().toISOString(),status:'closed',history:[]};db.payrollRuns.push(run);audit('تقفيل محلي: '+run.employeeName+' من '+period.from+' إلى '+period.to);return run}
function reopenPayroll(run,reason){if(run.status!=='closed')throw Error('التقفيل مفتوح بالفعل');if(!reason?.trim())throw Error('سبب إعادة الفتح مطلوب');run.status='reopened';run.history.push({at:new Date().toISOString(),action:'reopened',reason:reason.trim()});db.payrollDrafts[payrollKey(run.employeeId,run.period)]=structuredClone(run.draft);audit('إعادة فتح تقفيل '+run.employeeName+' — '+reason.trim())}
function payrollLineItems(s){const c=s.calculation,d=s.draft;return [...((s.excludedOpenShiftCount??(s.status==='closed'?0:s.attendance.open.length))>0?[['ورديات مفتوحة مستبعدة من الحساب',String(s.excludedOpenShiftCount??s.attendance.open.length)+' وردية — غير محسوبة في المبلغ']]:[]),['ساعات الحضور المدفوعة (شاملة البريك)',s.attendance.hours.toFixed(s.attendance.payrollHoursDecimals===2?2:4)+' ساعة'],...(c.manualHours?[['ساعات يدوية مضافة من الإدارة',c.manualHours.toFixed(s.attendance.payrollHoursDecimals===2?2:4)+' ساعة'],['إجمالي الساعات المحتسبة في الأجر',c.hours.toFixed(s.attendance.payrollHoursDecimals===2?2:4)+' ساعة']]:[]),...(s.attendance.openingHours?[['منها رصيد افتتاحي قبل التطبيق ('+s.attendance.openingShifts+' شيفت)',Number(s.attendance.openingHours).toFixed(s.attendance.payrollHoursDecimals===2?2:4)+' ساعة']]:[]),['سعر الساعة',currency(c.rate)],['أجر الحضور = الساعات × السعر',currency(c.base)],...(c.classAmount?[['مستحقات كلاسات ('+c.classCount+' كلاس × ٣٠ ج)',currency(c.classAmount)]]:[]),...(d.type==='captain'?[['إجمالي البرايفيت المدخل',currency(c.privateTotal)],['نصيب الكابتن من البرايفيت ٥٠٪',currency(c.privateShare)],['مسحوبات البرايفيت',currency(c.privateDraw)]]:[]),['البونص',currency(c.bonus)],...(d.type!=='housekeeping'?[['الحافز',currency(c.incentive)]]:[]),...(d.type==='sales'?[['التارجيت',d.targetAchieved?'متحقق':'غير متحقق'],['مكافأة التارجيت المستحقة',currency(c.targetBonus)]]:[]),[d.type==='captain'?'مسحوبات الكابتن':'المسحوبات',currency(c.draw)],...(c.lines||[]).map(l=>[(l.sign==='+'?'إضافة':'خصم')+' — '+l.label+' ('+l.reason+')',(l.sign==='+'?'+':'−')+' '+currency(l.amount)]),['إجمالي المستحقات قبل المسحوبات',currency(c.earnings)],['إجمالي المسحوبات',currency(c.withdrawals)],['الصافي المستحق',currency(c.total)]]}
function payslipHTML(s,closed=false){const c=s.calculation;return `<div class="payslip-paper" id="payrollPaper"><div class="report-brand"><div><b>ENERGY <span>STAFF</span></b><p>كشف تقفيل مرتب ${closed?'— مقفول محليًا':'— مسودة'}</p></div><div>${esc(s.period.from)} إلى ${esc(s.period.to)}<br><small>${closed?'تاريخ التقفيل: '+stamp(s.closedAt):'تاريخ المعاينة: '+stamp(new Date().toISOString())}</small></div></div><div class="payslip-person"><h2>${esc(s.employeeName)}</h2><p>${esc(payrollTypes[s.draft.type])} • ${esc(s.branch)}${s.external?' • اسم مُدخل يدويًا — غير مسجل بالنظام':''}</p></div><div class="payslip-total ${c.total<0?'negative-total':''}"><span>${c.total<0?'رصيد سالب — المسحوبات أكبر من المستحق':'صافي المستحق'}</span><strong>${currency(c.total)}</strong><small>${s.attendance.hours.toFixed(s.attendance.payrollHoursDecimals===2?2:4)} ساعة حضور • البريك مدفوع بالكامل</small></div><table><tbody>${payrollLineItems(s).map(([t,v])=>`<tr><td>${esc(t)}</td><td>${esc(v)}</td></tr>`).join('')}</tbody></table>${s.draft.notes?`<p class="payroll-notes">ملاحظات: ${esc(s.draft.notes)}</p>`:''}<h3>تفاصيل ساعات الحضور</h3><div class="table-wrap"><table><tr><th>الحضور بالقاهرة</th><th>الانصراف بالقاهرة</th><th>الساعات داخل الفترة</th><th>المصدر</th></tr>${s.attendance.closed.map(p=>`<tr><td>${stamp(p.in)}</td><td>${stamp(p.out)}</td><td>${(p.milliseconds/36e5).toFixed(s.attendance.payrollHoursDecimals===2?2:4)}</td><td>${p.source}</td></tr>`).join('')}${(s.attendance.opening||[]).map(o=>`<tr><td>${esc(o.date)}</td><td>—</td><td>${Number(o.hours).toFixed(s.attendance.payrollHoursDecimals===2?2:4)}</td><td>رصيد افتتاحي إداري — ${o.shifts} شيفت × ${o.hoursPerShift} ساعة${o.reason?' — '+esc(o.reason):''}</td></tr>`).join('')}${s.external&&!s.attendance.closed.length&&!(s.attendance.opening||[]).length?'<tr><td colspan="4">اسم مُدخل يدويًا — لا يوجد سجل حضور على النظام؛ الساعات مُدخلة يدويًا من الإدارة</td></tr>':''}</table></div><div class="report-signatures"><span>الموظف<br>________________</span><span>إعداد الحسابات<br>________________</span><span>اعتماد الإدارة<br>________________</span></div><p class="report-disclaimer">جميع المبالغ بالجنيه المصري • ${s.attendance.payrollHoursDecimals===2?'ساعات الحضور تقرب لرقمين عشريين قبل حساب الأجر • ':''}تقريب المبالغ لأقرب قرش بعد حساب المكون بالكامل • ساعات البريك لا تخصم • تجاوزات البريك والنقاط منفصلة، ولا يوجد خصم منها هنا • ${closed?'نسخة محفوظة وقت التقفيل':'مسودة قابلة للتغيير'} • ليس إثباتًا لصرف نقدي • بيانات هذه النسخة محفوظة محليًا.</p></div>`}
let pdfLibsPromise=null;
function loadPDFLibs(){if(window.html2canvas&&window.jspdf)return Promise.resolve();if(!pdfLibsPromise){const load=src=>new Promise((res,rej)=>{const t=document.createElement('script');t.src=src;t.onload=res;t.onerror=()=>rej(new Error('تعذر تحميل مكتبة PDF'));document.head.appendChild(t)});pdfLibsPromise=load('assets/vendor/html2canvas.min.js').then(()=>load('assets/vendor/jspdf.umd.min.js')).catch(e=>{pdfLibsPromise=null;throw e})}return pdfLibsPromise}
async function buildSlipPdfFile(el,filename){await loadPDFLibs();const cs=getComputedStyle(el);const bg=cs.backgroundColor&&cs.backgroundColor!=='rgba(0, 0, 0, 0)'?cs.backgroundColor:'#ffffff';const maxPixels=12000000;const scale=Math.min(2,Math.max(1,Math.sqrt(maxPixels/(el.scrollWidth*el.scrollHeight))));const canvas=await html2canvas(el,{scale,backgroundColor:bg,useCORS:true,logging:false});const {jsPDF}=window.jspdf;const pdf=new jsPDF({unit:'mm',format:'a4',orientation:'portrait'});const pageW=210,pageH=297,margin=8,imgW=pageW-2*margin;const pagePxH=canvas.width*(pageH-2*margin)/imgW;let y=0,page=0;while(y<canvas.height){const h=Math.min(pagePxH,canvas.height-y);const slice=document.createElement('canvas');slice.width=canvas.width;slice.height=Math.ceil(h);const ctx=slice.getContext('2d');ctx.fillStyle=bg;ctx.fillRect(0,0,slice.width,slice.height);ctx.drawImage(canvas,0,y,canvas.width,h,0,0,canvas.width,h);if(page)pdf.addPage();pdf.addImage(slice.toDataURL('image/jpeg',0.92),'JPEG',margin,margin,imgW,h*imgW/canvas.width);y+=h;page++}return new File([pdf.output('blob')],filename,{type:'application/pdf'})}
async function shareSlipPDF(s){try{if(!closedPayroll(s.id)&&!db.payrollDrafts[payrollKey(s.id)])return toast('احفظ مسودة الموظف أولًا');const snap=closedPayroll(s.id)||savedSnapshot(s.id);const el=document.getElementById('payrollPaper');if(!el)throw new Error('كشف الموظف غير ظاهر على الشاشة');const fname='كشف-مرتب-'+s.name+'-'+payrollPeriod.from+'.pdf';toast('جاري تجهيز ملف PDF...');const file=await buildSlipPdfFile(el,fname);if(navigator.canShare&&navigator.canShare({files:[file]})){try{await navigator.share({files:[file],title:fname});return}catch(e){if(e&&e.name==='AbortError')return}}const url=URL.createObjectURL(file),a=document.createElement('a');a.href=url;a.download=fname;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);toast('تم تحميل ملف PDF — تقدر تبعته من التنزيلات')}catch(e){console.error(e);toast('تعذر إنشاء PDF — هيتفتح للطباعة');document.body.classList.add('printing-payroll');window.print()}}

function payrollPreview(id){const closed=closedPayroll(id);let snapshot;try{snapshot=closed||savedSnapshot(id)}catch(e){return `<div class="empty">${esc(e.message)} — احفظ نوع الموظف وسعر الساعة لعرض الكشف.</div>`}const changed=closed&&closed.attendance.fingerprint!==attendanceHours(id,closed.period).fingerprint;return `${changed?'<div class="notice">سجل الحضور اتغير بعد التقفيل. الكشف المقفول يحتفظ بأرقامه؛ أعد فتحه بسبب واضح لو محتاج تحديثه.</div>':''}${snapshot.attendance.open.length?'<div class="notice">فيه ورديات مفتوحة مستبعدة من المبلغ؛ ممكن التقفيل من غير تعديل سجل الحضور.</div>':''}${snapshot.attendance.overlap?'<div class="notice">في سجلات متداخلة؛ راجعها قبل التقفيل.</div>':''}${payslipHTML(snapshot,!!closed)}<div class="toolbar no-print"><button id="slipCSV">↓ تصدير كشف الموظف CSV</button><button id="slipPrint">مشاركة / حفظ PDF للموظف</button>${closed?'<button id="reopenPayroll">إعادة فتح بسبب</button>':'<button id="closePayroll" class="primary">تقفيل وحفظ نسخة</button>'}</div>`}
function payrollLineRowHTML(l={}){const isC=l.label==='كلاسيز',isD=l.label==='أيام مدفوعة الأجر';return '<div class="payroll-line-row"><select data-line-label>'+PAYROLL_LINE_LABELS.map(x=>'<option '+(l.label===x?'selected':'')+'>'+x+'</option>').join('')+'</select><select data-line-sign><option value="+" '+(l.sign!=='-'?'selected':'')+'>إضافة ＋</option><option value="-" '+(l.sign==='-'?'selected':'')+'>خصم −</option></select><span class="line-amount-wrap" style="display:flex;gap:6px;width:100%"><input data-line-class-price type="number" min="0" step="0.01" inputmode="decimal" placeholder="سعر الكلاس" value="'+esc(l.classPrice??'')+'"'+(isC?'':' hidden')+'><input data-line-class-count type="number" min="0" step="1" inputmode="numeric" placeholder="عدد الكلاسات" value="'+esc(l.classCount??'')+'"'+(isC?'':' hidden')+'><input data-line-day-count type="number" min="0" step="1" inputmode="numeric" placeholder="عدد الأيام" value="'+esc(l.dayCount??'')+'"'+(isD?'':' hidden')+'><input data-line-day-rate type="number" min="0" step="0.01" inputmode="decimal" placeholder="سعر اليوم" value="'+esc(l.dayRate??'')+'"'+(isD?'':' hidden')+'><input data-line-amount type="number" min="0" step="0.01" inputmode="decimal" placeholder="'+(isC?'يتحسب تلقائي = السعر × العدد':(isD?'يتحسب تلقائي = عدد الأيام × سعر اليوم':'المبلغ بالجنيه'))+'" value="'+esc(l.amount??'')+'"'+((isC||isD)?' readonly':'')+'></span><input data-line-reason maxlength="200" placeholder="السبب (إجباري)" value="'+esc(l.reason||'')+'"><button type="button" data-line-remove title="حذف البند">✕</button></div>'}
function syncClassLineRow(row){const lbl=row.querySelector('[data-line-label]').value;const isC=lbl==='كلاسيز',isD=lbl==='أيام مدفوعة الأجر';const p=row.querySelector('[data-line-class-price]'),n=row.querySelector('[data-line-class-count]'),dc=row.querySelector('[data-line-day-count]'),dr=row.querySelector('[data-line-day-rate]'),a=row.querySelector('[data-line-amount]');if(!p||!n||!dc||!dr||!a)return;p.hidden=n.hidden=!isC;dc.hidden=dr.hidden=!isD;a.readOnly=isC||isD;a.placeholder=isC?'يتحسب تلقائي = السعر × العدد':(isD?'يتحسب تلقائي = عدد الأيام × سعر اليوم':'المبلغ بالجنيه');if(isC){const pv=parseFloat(p.value),nv=parseFloat(n.value);a.value=(pv>0&&nv>0)?String(Math.round(pv*nv*100)/100):''}else if(isD){const nv=parseFloat(dc.value),rv=parseFloat(dr.value);a.value=(nv>0&&rv>0)?String(Math.round(nv*rv*100)/100):''}}
function collectPayrollLines(form){return [...form.querySelectorAll('.payroll-line-row')].map(r=>{const label=r.querySelector('[data-line-label]').value,sign=r.querySelector('[data-line-sign]').value,price=(r.querySelector('[data-line-class-price]')||{}).value||'',count=(r.querySelector('[data-line-class-count]')||{}).value||'',dayCount=(r.querySelector('[data-line-day-count]')||{}).value||'',dayRate=(r.querySelector('[data-line-day-rate]')||{}).value||'';let amount=r.querySelector('[data-line-amount]').value,reason=r.querySelector('[data-line-reason]').value;if(label==='كلاسيز'){const pv=parseFloat(price),nv=parseFloat(count);amount=(pv>0&&nv>0)?String(Math.round(pv*nv*100)/100):'';if(!String(reason).trim()&&pv>0&&nv>0)reason=count+' كلاس × '+price+' ج'}if(label==='أيام مدفوعة الأجر'){const nv=parseFloat(dayCount),rv=parseFloat(dayRate);amount=(nv>0&&rv>0)?String(Math.round(nv*rv*100)/100):'';if(!String(reason).trim()&&nv>0&&rv>0)reason=dayCount+' يوم × '+dayRate+' ج'}const l={label,sign,amount,reason};if(label==='كلاسيز'){l.classPrice=price;l.classCount=count}if(label==='أيام مدفوعة الأجر'){l.dayCount=dayCount;l.dayRate=dayRate}return l}).filter(l=>l.amount!==''||l.reason!==''||String(l.classPrice||'')!==''||String(l.classCount||'')!==''||String(l.dayCount||'')!==''||String(l.dayRate||'')!=='')}
function payrollSummaryData(s,draftLike){const a=attendanceHours(s.id,payrollPeriod);let calc=null,err='';try{calc=payrollCompute(draftLike,a,classPayFor(s.id,payrollPeriod))}catch(e){err=e.message}const man=(()=>{try{return manualHoursValue(draftLike.manualHours)}catch{return 0}})();return {a,calc,err,man,shifts:a.closed.length+((a.opening||[]).reduce((n,o)=>n+(Number(o.shifts)||0),0))}}
function payrollSummaryHTML(s,draftLike){const x=payrollSummaryData(s,draftLike),total=x.a.hours+x.man;return `<div class="payroll-summary" id="payrollSummary"><div class="ps-name">${esc(s.name)} <small>${esc(s.branch||'')}</small></div><div class="ps-grid"><div><span>ساعات الحضور المسجلة</span><b id="psHours">${x.a.hours.toFixed(2)}</b><small>${x.shifts} وردية${x.a.open.length?' • '+x.a.open.length+' مفتوحة (مش محسوبة)':''}</small></div><div><span>ساعات يدوية</span><b id="psManual">${x.man.toFixed(2)}</b></div><div><span>إجمالي الساعات المحسوبة</span><b id="psTotal">${total.toFixed(2)}</b></div><div><span>الصافي المتوقع</span><b id="psNet">${x.calc?currency(x.calc.total):'—'}</b><small id="psErr">${x.calc?'':esc(x.err)}</small></div></div>${x.a.open.length?'<div class="ps-warn">الورديات المفتوحة مش محسوبة في المبلغ، ومش هتمنع التقفيل.</div>':''}</div>`}
function payrollNavHTML(employees,s){const i=employees.findIndex(e=>e.id===s.id);const prev=employees[i-1],next=employees[i+1];return `<div class="payroll-nav no-print"><button type="button" data-pr-nav="${prev?prev.id:''}" ${prev?'':'disabled'}>→ السابق</button><span>${i+1} / ${employees.length}</span><button type="button" data-pr-nav="${next?next.id:''}" ${next?'':'disabled'}>التالي ←</button></div>`}
function payrollView(){const baseEmployees=payrollPeopleBase(),employees=payrollPeople();if(!employees.some(s=>s.id===payrollEmployee))payrollEmployee=employees[0]?.id;const s=employees.find(s=>s.id===payrollEmployee),d=s?payrollDraft(s.id):null,closed=s?closedPayroll(s.id):null,remembered=s&&!db.payrollDrafts[payrollKey(s.id)]&&!!((db.hourlyProfiles||{})[s.id]||{}).hourlyRate;return `<div class="notice no-print">تقفيل على ساعات الحضور الفعلية كاملة، والبريك إضافي لا يخصم من الأجر. التقفيل يحفظ نسخة ثابتة، ولا يسجل صرفًا ماليًا. هذه نسخة محلية تجريبية. قواعد خصومات الأذونات والتأخير مقترحة ولم تُفعَّل في التقفيل بعد.</div>${card('فترة المرتبات',`<form class="toolbar payroll-period" id="payrollPeriod"><label>من<input required type="date" name="from" value="${payrollPeriod.from}"></label><label>إلى<input required type="date" name="to" value="${payrollPeriod.to}"></label><button class="primary">عرض الساعات والتقفيل</button><button type="button" id="payrollAllCSV">↓ ملخص كل الموظفين</button></form>`)}${payrollFilterBarHTML(baseEmployees,employees)}${card('ساعات كل موظف ومستحقاته',`<div class="table-wrap"><table><tr><th>الموظف</th><th>القسم</th><th>ساعات الحضور</th><th>ورديات مفتوحة</th><th>نوع التقفيل</th><th>الصافي</th><th>الحالة</th><th>كشف الموظف</th></tr>${employees.map(e=>{const a=attendanceHours(e.id,payrollPeriod),r=closedPayroll(e.id),draft=payrollDraft(e.id);let total='غير مكتمل';try{total=currency((r?.calculation||payrollCompute(draft,a,classPayFor(e.id,payrollPeriod))).total)}catch{}return `<tr><td>${esc(e.name)}${e.external?' <small class=ext-tag>(اسم يدوي)</small>':''}</td><td>${esc(payrollDeptOf(e))}</td><td>${(r?.attendance.hours??a.hours).toFixed((r?.attendance||a).payrollHoursDecimals===2?2:4)}</td><td>${a.open.length}</td><td>${esc(payrollTypes[(r?.draft||draft).type]||'حدد النوع')}</td><td>${total}</td><td>${r?'مقفول محليًا':'مسودة'}</td><td><button data-payroll-employee="${e.id}">${e.id===payrollEmployee?'محدد ✓':'فتح الكشف'}</button>${e.external?`<button data-ext-remove="${e.id}" title="حذف الاسم اليدوي">✕</button>`:''}</td></tr>`}).join('')}</table></div>`)}${s?`<div class="payroll-layout"><section class="card payroll-editor no-print"><div class="card-head"><h2>بيانات تقفيل ${esc(s.name)}</h2></div><div class="payroll-top">${payrollNavHTML(employees,s)}${payrollSummaryHTML(s,d)}</div>${payrollExtFormHTML()}<form id="payrollEmployeeForm" class="payroll-fields"><fieldset ${closed?'disabled':''}><label>الموظف<select name="employeePick" id="payrollEmployeePick" ${closed?'disabled':''}>${employees.map(e=>`<option value="${e.id}" ${e.id===s.id?'selected':''}>${esc(e.name)}${e.external?' — اسم يدوي':''}</option>`).join('')}</select><small>اختار الموظف اللي هيتعمله كشف القبض — اسمه بيتحط في الكشف.</small></label><label>نوع الموظف<select name="type" required><option value="">اختار النوع</option>${Object.entries(payrollTypes).map(([k,t])=>`<option value="${k}" ${d.type===k?'selected':''}>${t}</option>`).join('')}</select></label><label>الفرع<select name="branch">${db.branches.map(b=>`<option value="${esc(b.name)}" ${((d.branch||s.branch)===b.name)?'selected':''}>${esc(b.name)}</option>`).join('')}</select><small>فرع الموظف في الكشف والتقارير — التغيير هنا يحدّث ملف الموظف.</small></label>${payrollAmountField('سعر الساعة بالجنيه','hourlyRate',d.hourlyRate)}${remembered?'<small class="pr-remembered">✓ نوع الموظف وسعر الساعة محفوظين من آخر تقفيل — عدّلهم لو حاجة اتغيرت.</small>':''}${payrollAmountField('ساعات يدوية إضافية — تتضرب في سعر الساعة','manualHours',d.manualHours)}<small>ساعات الحضور المسجلة بتتحسب تلقائي، والخانة دي بتضيف عليها (تفيد لو الساعات مش متسجلة على النظام).</small><div class="mh-total" id="mhTotal"></div><div class="captain-fields" ${d.type!=='captain'?'hidden':''}>${payrollAmountField('إجمالي البرايفيت — نصيب الكابتن ٥٠٪ تلقائيًا','privateTotal',d.privateTotal)}${payrollAmountField('مسحوبات من البرايفيت','privateDraw',d.privateDraw)}</div>${payrollAmountField(d.type==='captain'?'مسحوبات الكابتن':'المسحوبات','employeeDraw',d.employeeDraw)}${payrollAmountField('البونص','bonus',d.bonus)}<div class="incentive-fields" ${d.type==='housekeeping'||!d.type?'hidden':''}>${payrollAmountField('الحافز','incentive',d.incentive)}</div><div class="sales-fields" ${d.type!=='sales'?'hidden':''}><label class="permission-item"><input type="checkbox" name="targetAchieved" ${d.targetAchieved?'checked':''}>التارجيت اتحقق</label>${payrollAmountField('مكافأة تحقيق التارجيت','targetBonus',d.targetBonus)}<small>المبلغ يدخل الصافي فقط عند تفعيل «التارجيت اتحقق».</small></div><fieldset class="payroll-lines-box"><legend>بنود يدوية على التقفيلة (كلاسيز / أيام مدفوعة الأجر / بدل إشراف / جزاء إداري / إدراكات عمل…)</legend><div id="payrollLines">${(d.lines||[]).map(l=>payrollLineRowHTML(l)).join('')}</div><button type="button" id="addPayrollLine">＋ إضافة بند</button><small>كل بند لازم يتسجل بسببه — بيظهر في كشف المرتب وملف الـ CSV. بند «كلاسيز» بيتحسب تلقائي = سعر الكلاس × عدد الكلاسات وسببه بيتكتب لوحده. وبند «أيام مدفوعة الأجر» بيتحسب = عدد الأيام × سعر اليوم بنفس الطريقة. مفيش خصم تلقائي من النقاط أو التنبيهات.</small></fieldset><label>ملاحظات<textarea name="notes" rows="3" maxlength="1000">${esc(d.notes||'')}</textarea></label><div class="payroll-actions"><button class="primary" type="submit" data-pr-mode="save">حفظ المسودة وحساب الصافي</button><button class="primary pr-close" type="submit" data-pr-mode="close">حفظ وتقفيل مباشرة</button></div></fieldset>${closed?'<p>البيانات مقفولة؛ أعد فتح التقفيل للتعديل.</p>':''}<p id="payrollDirty" class="payroll-dirty" hidden>في تعديلات غير محفوظة. احفظها لتحديث الكشف.</p></form></section><div id="payrollPreview">${payrollPreview(s.id)}</div></div>`:'<p class="empty">لا يوجد موظفون مطابقون للفلتر المحدد</p>'}${card('سجل التقفيلات',`<div class="table-wrap"><table><tr><th>الموظف</th><th>الفترة</th><th>الساعات المحفوظة</th><th>الصافي</th><th>الحالة</th><th>التصدير</th></tr>${db.payrollRuns.filter(r=>employees.some(e=>e.id===r.employeeId)).slice().reverse().map(r=>`<tr><td>${esc(r.employeeName)}${r.external?' <small class=ext-tag>(اسم يدوي)</small>':''}</td><td>${r.period.from} — ${r.period.to}</td><td>${r.attendance.hours.toFixed(4)}</td><td>${currency(r.calculation.total)}</td><td>${r.status==='closed'?'مقفول محليًا':'أعيد فتحه'}${r.history.length?'<br>'+esc(r.history.at(-1).reason):''}</td><td><button data-run-export="${r.id}">CSV محفوظ</button></td></tr>`).join('')}</table></div>`)}`}
function payrollCSVRows(s){return [['كشف مرتب',s.employeeName],['النوع',payrollTypes[s.draft.type]],['الفرع',s.branch],['من',s.period.from],['إلى',s.period.to],['الحالة',s.status==='closed'?'مقفول محليًا':'مسودة / أعيد فتحه'],...((s.excludedOpenShiftCount??(s.status==='closed'?0:s.attendance.open.length))>0?[['ورديات مفتوحة مستبعدة من الحساب',String(s.excludedOpenShiftCount??s.attendance.open.length)]]:[]),['سعر الساعة بالجنيه',decimal(s.calculation.rate)],['ساعات الحضور شاملة البريك',s.attendance.hours.toFixed(8)],...(s.calculation.manualHours?[['ساعات يدوية مضافة',s.calculation.manualHours.toFixed(8)],['إجمالي الساعات المحتسبة',s.calculation.hours.toFixed(8)]]:[]),...(s.attendance.openingHours?[['منها رصيد افتتاحي قبل التطبيق (ساعات)',Number(s.attendance.openingHours).toFixed(8)],['شيفتات الرصيد الافتتاحي',String(s.attendance.openingShifts)]]:[]),['أجر الحضور بالجنيه',decimal(s.calculation.base)],...(s.calculation.classAmount?[['مستحقات كلاسات ('+s.calculation.classCount+' كلاس)',decimal(s.calculation.classAmount)]]:[]),...(s.draft.type==='captain'?[['إجمالي البرايفيت',decimal(s.calculation.privateTotal)],['نصيب الكابتن 50%',decimal(s.calculation.privateShare)],['مسحوبات البرايفيت',decimal(s.calculation.privateDraw)]]:[]),['البونص',decimal(s.calculation.bonus)],...(s.draft.type!=='housekeeping'?[['الحافز',decimal(s.calculation.incentive)]]:[]),...(s.draft.type==='sales'?[['التارجيت متحقق',s.draft.targetAchieved?'نعم':'لا'],['مكافأة التارجيت المحتسبة',decimal(s.calculation.targetBonus)]]:[]),['المسحوبات',decimal(s.calculation.draw)],...(s.calculation.lines||[]).map(l=>[(l.sign==='+'?'إضافة':'خصم')+' — '+l.label+' — '+l.reason,(l.sign==='-'?'-':'')+decimal(l.amount)]),['إجمالي المستحقات',decimal(s.calculation.earnings)],['إجمالي المسحوبات',decimal(s.calculation.withdrawals)],['الصافي',decimal(s.calculation.total)],['ملاحظات',s.draft.notes||''],[],['الحضور بالقاهرة','الانصراف بالقاهرة','الساعات داخل الفترة','المصدر'],...s.attendance.closed.map(p=>[stamp(p.in),stamp(p.out),(p.milliseconds/36e5).toFixed(8),p.source]),...(s.attendance.opening||[]).map(o=>[o.date,'—',Number(o.hours).toFixed(8),'رصيد افتتاحي إداري — '+(o.reason||'')]),[],['البريك مدفوع بالكامل. كشف محلي وليس إثبات صرف.']]}
function downloadPayrollCSV(rows,name){const quote=v=>{let s=String(v??'');if(/^[\s]*[=+@-]/.test(s)&&!/^[-]?\d+(?:\.\d+)?$/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};const blob=new Blob(['\ufeff'+rows.map(r=>r.map(quote).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function exportPaySummary(){const rows=[['الموظف','من','إلى','النوع','الساعات المدفوعة','سعر الساعة','أجر الحضور','نصيب البرايفيت','البونص','الحافز','مكافأة التارجيت','مسحوبات البرايفيت','المسحوبات','صافي البنود اليدوية','الصافي','الحالة']];for(const s of payrollPeople()){try{const r=closedPayroll(s.id)||savedSnapshot(s.id);const c=r.calculation;rows.push([s.name+(s.external?' (اسم يدوي — غير مسجل)':''),r.period.from,r.period.to,payrollTypes[r.draft.type],r.attendance.hours.toFixed(8),decimal(c.rate),decimal(c.base),decimal(c.privateShare),decimal(c.bonus),decimal(c.incentive),decimal(c.targetBonus),decimal(c.privateDraw),decimal(c.draw),decimal((c.linesAdd||0)-(c.linesSub||0)),decimal(c.total),r.status==='closed'?'مقفول محليًا':'مسودة'])}catch{rows.push([s.name+(s.external?' (اسم يدوي — غير مسجل)':''),payrollPeriod.from,payrollPeriod.to,'غير مكتمل',attendanceHours(s.id,payrollPeriod).hours.toFixed(8),'','','','','','','','','','','لم يحدد النوع / المبالغ'])}}downloadPayrollCSV(rows,'Energy-Payroll-Summary-'+payrollPeriod.from+'.csv')}
function payrollReadForm(form){const f=new FormData(form),d={...Object.fromEntries(f),targetAchieved:f.has('targetAchieved'),lines:collectPayrollLines(form)};delete d.employeePick;return d}
function payrollLiveSummary(s,form){try{const d=payrollReadForm(form);const x=payrollSummaryData(s,d);const set=(id,v)=>{const el=document.getElementById(id);if(el)el.textContent=v};set('psManual',x.man.toFixed(2));set('psTotal',(x.a.hours+x.man).toFixed(2));set('psNet',x.calc?currency(x.calc.total):'—');set('psErr',x.calc?'':x.err);const mh=document.getElementById('mhTotal');if(mh)mh.innerHTML='ساعات الحضور '+x.a.hours.toFixed(2)+' + ساعات يدوية '+x.man.toFixed(2)+' = <b>إجمالي '+(x.a.hours+x.man).toFixed(2)+' ساعة</b>'}catch(e){}}
function bindPayroll(){const s=payrollFind(payrollEmployee);$('#payrollPeriod').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),p={from:f.get('from'),to:f.get('to')};try{periodBounds(p);payrollPeriod=p;render()}catch(err){toast(err.message)}};$('#payrollAllCSV').onclick=exportPaySummary;const pfd=$('#payrollFilterDept');if(pfd)pfd.onchange=e=>{if(!payrollAutoSaveDraft(s)){e.target.value=payrollFilterDept;return}payrollFilterDept=e.target.value;render()};const pfs=$('#payrollFilterStatus');if(pfs)pfs.onchange=e=>{if(!payrollAutoSaveDraft(s)){e.target.value=payrollFilterStatus;return}payrollFilterStatus=e.target.value;render()};const pfb=$('#payrollFilterBranch');if(pfb)pfb.onchange=e=>{const g=$('#branch');if(g){g.value=e.target.value;g.dispatchEvent(new Event('change'))}else render()};document.querySelectorAll('[data-payroll-employee]').forEach(b=>b.onclick=()=>{if(!payrollAutoSaveDraft(s))return;payrollEmployee=pid(b.dataset.payrollEmployee);render()});document.querySelectorAll('[data-run-export]').forEach(b=>b.onclick=()=>{const r=db.payrollRuns.find(r=>r.id===b.dataset.runExport);downloadPayrollCSV(payrollCSVRows(r),'Energy-Payslip-'+r.employeeId+'-'+r.period.from+'.csv')});document.querySelectorAll('[data-ext-remove]').forEach(b=>b.onclick=()=>removePayrollExternal(b.dataset.extRemove));const extForm=$('#payrollExtForm');if(extForm)extForm.onsubmit=e=>{e.preventDefault();try{addPayrollExternal(new FormData(extForm).get('extName'))}catch(err){toast(err.message)}};if(!s)return;const form=$('#payrollEmployeeForm');function payrollAutoSaveDraft(emp){try{const f0=$('#payrollEmployeeForm');const dirty=$('#payrollDirty');if(!f0||!emp||!dirty||dirty.hidden)return true;if(closedPayroll(emp.id))return true;const d=payrollReadForm(f0);try{const a=attendanceHours(emp.id,payrollPeriod);payrollCompute(d,a);db.payrollDrafts[payrollKey(emp.id)]=d;db.hourlyProfiles[emp.id]={type:d.type,hourlyRate:d.hourlyRate};audit('حفظ مسودة تلقائي عند التبديل لـ '+emp.name);toast('اتحفظت مسودة '+emp.name+' تلقائيًا')}catch(verr){db.payrollDrafts[payrollKey(emp.id)]=d;audit('احتفاظ بمسودة غير مكتملة لـ '+emp.name);toast('اتحفظت بيانات '+emp.name+' زي ما هي — كمّل النوع والسعر بعدين')}return true}catch(err){return true}}
document.querySelectorAll('[data-pr-nav]').forEach(b=>b.onclick=()=>{if(!b.dataset.prNav)return;if(!payrollAutoSaveDraft(s))return;payrollEmployee=pid(b.dataset.prNav);render();window.scrollTo({top:0})});document.querySelectorAll('[data-payroll-employee]').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>document.getElementById('payrollSummary')?.scrollIntoView({block:'start'}),50)));form.querySelector('#payrollEmployeePick').onchange=e=>{if(!payrollAutoSaveDraft(s)){e.target.value=String(s.id);return}payrollEmployee=pid(e.target.value);render()};form.oninput=e=>{if(e&&e.target&&e.target.name==='employeePick')return;payrollLiveSummary(s,form);$('#payrollDirty').hidden=false;document.querySelectorAll('#closePayroll,#slipCSV,#slipPrint').forEach(b=>b.disabled=true)};form.querySelector('[name="type"]').onchange=e=>{form.querySelector('.captain-fields').hidden=e.target.value!=='captain';form.querySelector('.sales-fields').hidden=e.target.value!=='sales';form.querySelector('.incentive-fields').hidden=!e.target.value||e.target.value==='housekeeping'};payrollLiveSummary(s,form);$('#addPayrollLine').onclick=()=>{$('#payrollLines').insertAdjacentHTML('beforeend',payrollLineRowHTML());form.dispatchEvent(new Event('input',{bubbles:true}))};$('#payrollLines').addEventListener('change',e=>{const sel=e.target.closest('[data-line-label]');if(!sel)return;syncClassLineRow(sel.closest('.payroll-line-row'));form.dispatchEvent(new Event('input',{bubbles:true}))});$('#payrollLines').addEventListener('input',e=>{if(!e.target.closest('[data-line-class-price],[data-line-class-count],[data-line-day-count],[data-line-day-rate]'))return;syncClassLineRow(e.target.closest('.payroll-line-row'))});form.addEventListener('click',e=>{const b=e.target.closest('[data-line-remove]');if(b){b.closest('.payroll-line-row').remove();form.dispatchEvent(new Event('input',{bubbles:true}))}});form.onsubmit=e=>{e.preventDefault();if(closedPayroll(s.id))return toast('التقفيل مقفول');try{const f=new FormData(form),d={...Object.fromEntries(f),targetAchieved:f.has('targetAchieved'),lines:collectPayrollLines(form)};delete d.employeePick;const a=attendanceHours(s.id,payrollPeriod);payrollCompute(d,a);const branchVal=String(d.branch||'').trim();const st=allEmployees().find(x=>x.id===s.id);if(st&&branchVal&&st.branch!==branchVal){audit('تعديل فرع '+st.name+' إلى '+branchVal);st.branch=branchVal}else if(s.external){const xr=(db.payrollExternal||[]).find(x=>x.id===s.id);if(xr&&branchVal&&xr.branch!==branchVal){audit('تعديل فرع '+xr.name+' (اسم يدوي) إلى '+branchVal);xr.branch=branchVal}}const wantClose=e.submitter&&e.submitter.dataset.prMode==='close';if(wantClose){const prevDraft=db.payrollDrafts[payrollKey(s.id)],prevProfile=db.hourlyProfiles[s.id];db.payrollDrafts[payrollKey(s.id)]=d;db.hourlyProfiles[s.id]={type:d.type,hourlyRate:d.hourlyRate};try{const snap=savedSnapshot(s.id);if(!confirm('تقفيل '+s.name+'\nالساعات: '+snap.calculation.hours.toFixed(2)+' • الصافي: '+currency(snap.calculation.total)+(snap.attendance.open.length?'\nورديات مفتوحة مستبعدة من المبلغ: '+snap.attendance.open.length:'')+'\nيتم تثبيت الأرقام بدون تسجيل صرف نقدي. متأكد؟')){throw Error('__cancel__')}audit('حفظ مسودة مرتب '+s.name);closePayroll(s.id);const list=payrollPeople(),i=list.findIndex(x=>x.id===s.id),nx=list.slice(i+1).find(x=>!closedPayroll(x.id));if(nx)payrollEmployee=nx.id;render();toast('تم تقفيل '+s.name+(nx?' — الموظف التالي: '+nx.name:''))}catch(err){if(prevDraft===undefined)delete db.payrollDrafts[payrollKey(s.id)];else db.payrollDrafts[payrollKey(s.id)]=prevDraft;if(prevProfile===undefined)delete db.hourlyProfiles[s.id];else db.hourlyProfiles[s.id]=prevProfile;if(err.message!=='__cancel__')toast(err.message)}return}db.payrollDrafts[payrollKey(s.id)]=d;db.hourlyProfiles[s.id]={type:d.type,hourlyRate:d.hourlyRate};audit('حفظ مسودة مرتب '+s.name);render();toast('تم حساب وحفظ مسودة الموظف')}catch(err){toast(err.message)}};$('#slipCSV')?.addEventListener('click',()=>{try{const r=closedPayroll(s.id)||savedSnapshot(s.id);downloadPayrollCSV(payrollCSVRows(r),'Energy-Payslip-'+s.id+'-'+payrollPeriod.from+'.csv')}catch(e){toast(e.message)}});$('#slipPrint')?.addEventListener('click',()=>{shareSlipPDF(s)});$('#closePayroll')?.addEventListener('click',()=>{try{const snap=savedSnapshot(s.id);if(!confirm('تقفيل محلي للموظف '+s.name+' بصافي '+currency(snap.calculation.total)+'؟'+(snap.attendance.open.length?' ورديات مفتوحة مستبعدة من المبلغ: '+snap.attendance.open.length+'.':'')+' سيتم تثبيت الأرقام، بدون تسجيل صرف نقدي.'))return;closePayroll(s.id);db.hourlyProfiles[s.id]={type:snap.draft.type,hourlyRate:snap.draft.hourlyRate};render();toast('تم حفظ نسخة التقفيل المحلية')}catch(e){toast(e.message)}});$('#reopenPayroll')?.addEventListener('click',()=>safeSubmit('إعادة فتح التقفيل',field('سبب إعادة الفتح','reason'),f=>reopenPayroll(closedPayroll(s.id),f.get('reason'))))}
function closedByDeptCard(){
 const runs=(db.payrollRuns||[]).filter(r=>r.status==='closed'&&r.period.from<=payrollPeriod.to&&r.period.to>=payrollPeriod.from);
 const people=new Map(payrollPeople().map(p=>[String(p.id),p]));
 const deptOf=r=>{const p=people.get(String(r.employeeId));if(p)return payrollDeptOf(p);return (typeof PAYROLL_TYPE_DEPT!=='undefined'&&PAYROLL_TYPE_DEPT[r.draft.type])||'بدون قسم'};
 const rowHTML=r=>`<tr><td>${esc(r.employeeName)}${r.external?' <small class=ext-tag>(اسم يدوي)</small>':''}</td><td>${esc(r.branch||'—')}</td><td>${esc(payrollTypes[r.draft.type]||'—')}</td><td>${r.attendance.hours.toFixed(4)}</td><td>${currency(r.calculation.total)}</td><td>${esc(stamp(r.closedAt))}</td><td class="no-print"><button data-closed-slip="${r.id}">عرض الكشف</button></td></tr>`;
 const depts=[...new Set(runs.map(deptOf))];
 const blocks=depts.map(dept=>{
  const dlist=runs.filter(r=>deptOf(r)===dept);
  const dsum=dlist.reduce((a,r)=>({hours:a.hours+r.attendance.hours,total:a.total+r.calculation.total}),{hours:0,total:0});
  const branches=[...new Set(dlist.map(r=>r.branch||'—'))];
  const bhtml=branches.map(br=>{
   const blist=dlist.filter(r=>(r.branch||'—')===br);
   const bsum=blist.reduce((a,r)=>({hours:a.hours+r.attendance.hours,total:a.total+r.calculation.total}),{hours:0,total:0});
   return `<h4>${esc(br)} — ${blist.length} ${blist.length===1?'موظف مقفول':'موظفين مقفولين'}</h4><div class="table-wrap"><table><tr><th>الموظف</th><th>الفرع</th><th>النوع</th><th>الساعات المحفوظة</th><th>الصافي المحفوظ</th><th>وقت التقفيل</th><th class="no-print">الكشف المقفول</th></tr>${blist.map(rowHTML).join('')}<tr class="branch-report-total"><td>إجمالي ${esc(br)}</td><td>—</td><td>—</td><td>${bsum.hours.toFixed(4)}</td><td>${currency(bsum.total)}</td><td>—</td><td class="no-print"></td></tr></table></div>`;
  }).join('');
  return `<div class="branch-report-group"><h3>${esc(dept)} — ${dlist.length} ${dlist.length===1?'موظف مقفول':'موظفين مقفولين'} • الصافي ${currency(dsum.total)}</h3>${bhtml}</div>`;
 }).join('');
 const gsum=runs.reduce((a,r)=>({hours:a.hours+r.attendance.hours,total:a.total+r.calculation.total}),{hours:0,total:0});
 const slips=runs.map(r=>`<div class="branch-slip" data-closed-slip-box="${r.id}" hidden>${payslipHTML(r,true)}<div class="toolbar no-print"><button class="primary" data-closed-slip-print="${r.id}">طباعة / حفظ PDF للموظف</button></div></div>`).join('');
 return card('المقفولين حسب القسم والفرع — الفترة الحالية',`<div class="notice no-print">كل موظف اتقفل في الفترة الحالية، متجمّع حسب القسم وجواه كل فرع، مع صافي كل فرع وقسم والإجمالي العام. المسودات وغير المقفول مش بيدخلوا هنا — دي النسخ المقفولة بس.</div>${runs.length?blocks+`<div class="table-wrap"><table><tr class="branch-report-total"><td>الإجمالي العام — ${runs.length} ${runs.length===1?'موظف مقفول':'موظفين مقفولين'}</td><td>—</td><td>—</td><td>${gsum.hours.toFixed(4)}</td><td>${currency(gsum.total)}</td><td>—</td><td class="no-print"></td></tr></table></div>`:'<p class="empty">لا توجد تقفيلات مقفولة في الفترة دي لسه — أول ما تقفل أي موظف هيظهر هنا متجمّع حسب قسمه وفرعه.</p>'}${slips}`);
}
function bindClosedByDept(){
 document.querySelectorAll('[data-closed-slip]').forEach(b=>b.onclick=()=>{const box=document.querySelector('[data-closed-slip-box="'+b.dataset.closedSlip+'"]');if(box)box.hidden=!box.hidden});
 document.querySelectorAll('[data-closed-slip-print]').forEach(b=>b.onclick=()=>{const box=document.querySelector('[data-closed-slip-box="'+b.dataset.closedSlipPrint+'"]');if(!box)return;document.querySelectorAll('.print-target').forEach(x=>x.classList.remove('print-target'));box.classList.add('print-target');box.hidden=false;document.body.classList.add('printing-one-slip');window.print()});
}
function branchReportCard(){
 const runs=(db.payrollRuns||[]).filter(r=>r.status==='closed'&&r.period.from<=payrollPeriod.to&&r.period.to>=payrollPeriod.from);
 const branchNames=[...new Set(runs.map(r=>r.branch).filter(Boolean))];
 const visible=runs.filter(r=>!payrollReportBranch||r.branch===payrollReportBranch);
 const groups=[...new Set(visible.map(r=>r.branch||'—'))];
 const blocks=groups.map(branch=>{
  const list=visible.filter(r=>(r.branch||'—')===branch);
  const sums=list.reduce((a,r)=>({hours:a.hours+r.attendance.hours,earnings:a.earnings+r.calculation.earnings,withdrawals:a.withdrawals+r.calculation.withdrawals,total:a.total+r.calculation.total}),{hours:0,earnings:0,withdrawals:0,total:0});
  return `<div class="branch-report-group"><h3>${esc(branch)} — ${list.length} ${list.length===1?'موظف مقفول':'موظفين مقفولين'}</h3><div class="table-wrap"><table><tr><th>الموظف</th><th>النوع</th><th>الفترة المحفوظة</th><th>الساعات المحفوظة</th><th>إجمالي المستحقات</th><th>إجمالي المسحوبات والخصومات</th><th>الصافي المحفوظ</th><th class="no-print">الكشف المقفول</th></tr>${list.map(r=>`<tr><td>${esc(r.employeeName)}${r.external?' <small class=ext-tag>(اسم يدوي)</small>':''}</td><td>${esc(payrollTypes[r.draft.type]||'—')}</td><td>${esc(r.period.from)} — ${esc(r.period.to)}</td><td>${r.attendance.hours.toFixed(4)}</td><td>${currency(r.calculation.earnings)}</td><td>${currency(r.calculation.withdrawals)}</td><td>${currency(r.calculation.total)}</td><td class="no-print"><button data-branch-slip="${r.id}">عرض الكشف</button></td></tr>`).join('')}<tr class="branch-report-total"><td>إجمالي ${esc(branch)}</td><td>—</td><td>—</td><td>${sums.hours.toFixed(4)}</td><td>${currency(sums.earnings)}</td><td>${currency(sums.withdrawals)}</td><td>${currency(sums.total)}</td><td class="no-print"></td></tr></table></div></div>`;
 }).join('');
 const slips=visible.map(r=>`<div class="branch-slip" data-slip-box="${r.id}" hidden>${payslipHTML(r,true)}<div class="toolbar no-print"><button class="primary" data-slip-print="${r.id}">طباعة / حفظ PDF للموظف</button></div></div>`).join('');
 const paper=`<div class="report-paper branch-report-paper" id="branchReportPaper"><div class="report-brand"><div><b>ENERGY <span>STAFF</span></b><p>تقرير مرتبات الفرع — النسخ المقفولة</p></div><div>${esc(payrollPeriod.from)} إلى ${esc(payrollPeriod.to)}<br><small>صادر: ${stamp(new Date().toISOString())}</small></div></div>${visible.length?blocks:'<p class="empty">لا توجد تقفيلات محفوظة في الفترة دي'+(payrollReportBranch?' لفرع '+esc(payrollReportBranch):'')+' — التقرير بيعرض نسخ التقفيل المقفولة بس، من غير المسودات.</p>'}${visible.length?'<div class="report-signatures"><span>إعداد الحسابات<br>________________</span><span>اعتماد الإدارة<br>________________</span></div>':''}<p class="report-disclaimer">جميع المبالغ بالجنيه المصري ومحفوظة من وقت التقفيل • التقفيل لا يسجل صرفًا ماليًا • الأوقات بتوقيت القاهرة.</p></div>`;
 return `<div id="branchReportCard">${card('تقرير مرتبات الفرع — النسخ المقفولة فقط',`<div class="notice no-print">بيعرض بس النسخ اللي اتقفلت وتحفظت بفرع الموظف وقت التقفيل. المسودات وغير المقفول مش بيدخلوا فيه، وكل كشف بيتطبع لموظف واحد بس.</div><div class="toolbar no-print"><label>الفرع <select id="branchReportBranch"><option value="">كل الفروع</option>${branchNames.map(b=>`<option value="${esc(b)}" ${payrollReportBranch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></label><button class="primary" id="branchReportPrint">طباعة / حفظ PDF تقرير الفرع</button></div>${paper}${slips}`)}</div>`;
}
function bindBranchReport(){
 const sel=document.querySelector('#branchReportBranch');if(sel)sel.onchange=e=>{payrollReportBranch=e.target.value;render()};
 document.querySelectorAll('[data-branch-slip]').forEach(b=>b.onclick=()=>{const box=document.querySelector('[data-slip-box="'+b.dataset.branchSlip+'"]');if(box)box.hidden=!box.hidden});
 const printAll=document.querySelector('#branchReportPrint');if(printAll)printAll.onclick=()=>{document.querySelectorAll('.branch-slip').forEach(x=>x.hidden=false);document.body.classList.add('printing-branch-report');window.print()};
 document.querySelectorAll('[data-slip-print]').forEach(b=>b.onclick=()=>{const box=document.querySelector('[data-slip-box="'+b.dataset.slipPrint+'"]');if(!box)return;document.querySelectorAll('.print-target').forEach(x=>x.classList.remove('print-target'));box.classList.add('print-target');box.hidden=false;document.body.classList.add('printing-one-slip');window.print()});
}
function employeeHoursSummary(){const employee=$('#branch').value;return card('إجمالي ساعات كل موظف — البريك مدفوع',`<div class="table-wrap"><table><tr><th>الموظف</th><th>الفرع الحالي</th><th>الورديات المغلقة</th><th>الساعات المدفوعة</th><th>منها رصيد افتتاحي</th><th>المفتوحة</th></tr>${allEmployees().filter(s=>(!reportFilter.employee||s.id===Number(reportFilter.employee))).map(s=>{const rows=reportRows().filter(p=>p.employeeId===s.id);const opening=(db.attendanceOpening||[]).filter(o=>Number(o.employeeId)===Number(s.id)&&(!reportFilter.from||o.date>=reportFilter.from)&&(!reportFilter.to||o.date<=reportFilter.to));if(!rows.length&&!opening.length&&reportFilter.branch&&s.branch!==reportFilter.branch)return '';const closed=rows.filter(p=>p.out),hours=closed.reduce((sum,p)=>sum+(Date.parse(p.out)-Date.parse(p.in))/36e5,0),openingHours=opening.reduce((x,o)=>x+Number(o.hours||0),0),openingShifts=opening.reduce((x,o)=>x+Number(o.shifts||0),0);return `<tr><td>${esc(s.name)}</td><td>${esc(s.branch)}</td><td>${closed.length}</td><td>${(hours+openingHours).toFixed(4)}</td><td>${opening.length?openingShifts+' شيفت / '+openingHours.toFixed(2)+' س':'—'}</td><td>${rows.length-closed.length}</td></tr>`}).join('')}</table></div><p class="score-explain">تقرير الحضور يجمع الورديات حسب يوم بداية الوردية. تقفيل المرتبات يقسم ساعات الوردية العابرة لحدود الفترة حتى لا تتكرر بين فترتين.</p>`)}
render=function(){payrollRender();if(role!=='الإدارة')return;if(page==='payroll'){$('#app').innerHTML=payrollView()+closedByDeptCard()+branchReportCard();bindPayroll();bindClosedByDept();bindBranchReport()}if(page==='reports')$('#reportPaper').insertAdjacentHTML('beforeend',employeeHoursSummary())};
window.addEventListener('afterprint',()=>{document.body.classList.remove('printing-payroll');document.body.classList.remove('printing-branch-report');document.body.classList.remove('printing-one-slip');document.querySelectorAll('.print-target').forEach(x=>x.classList.remove('print-target'))});
render();
